SELECT , CASE STATUS WHEN 0 THEN '草稿' WHEN 1 THEN '生效中' WHEN 2 THEN '已解除' WHEN 3 THEN '已失效' ELSE '未知' END AS STATUS_NAME, CASE APPROVAL_STATUS WHEN 0 THEN '待审批' WHEN 1 THEN '已审批' WHEN 2 THEN '审批拒绝' ELSE '未知' END AS APPROVAL_STATUS_NAME FROM TBL_FINANCING_GUARANTEE WHERE 1=1
AND CONTRACT_NO LIKE '%' || #{contractNo} || '%'
AND GUARANTEE_TYPE = #{guaranteeType}
AND GUARANTOR LIKE '%' || #{guarantor} || '%'
AND BORROWER LIKE '%' || #{borrower} || '%'
AND START_DATE >= #{startDateBegin}
AND START_DATE <= #{startDateEnd}
AND END_DATE >= #{endDateBegin}
AND END_DATE <= #{endDateEnd}
AND STATUS = #{status}
AND APPROVAL_STATUS = #{approvalStatus}
AND ORG_ID = #{orgId}
ORDER BY CREATE_TIME DESC

